"use client";

import { FormEvent, useEffect, useMemo, useRef, useState } from "react";
import Sidebar from "../components/sidebar";
import { deleteRemote, loadRemote, loadRemotePage, saveRemote } from "../lib/remote-records";
import { exportExcel } from "../lib/excel-export";
import { normalizeDataRecord, validateDataRecord } from "../../lib/data-quality";

type ClientForm = {
  clientId: string; serviceDate: string; fullName: string; dateOfBirth: string; last4Ssn: string; ethnicity: string; gender: string;
  address: string; city: string; state: string; zip: string; phone: string; email: string; nationality: string; preferredLanguage: "English" | "Spanish" | "Other";
  householdSize: string; children: string; adults: string; seniors: string; spouseName: string; maritalStatus: string;
  immigrationStatus: string; income: string; socialServices: boolean; otherServices: boolean; immigration: boolean;
  healthAndWellness: boolean; workersResourceCenter: boolean; educationalEmpowerment: boolean; socialServiceDetails: string[]; legalImmigrationDetails: string[]; workerResourceDetails: string[]; educationalEmpowermentDetails: string[]; healthWellnessDetails: string[]; photo: string; files: string[]; caseNotes: string;
  tags: string[]; emergencyContactName: string; emergencyContactRelationship: string; emergencyContactPhone: string; emergencyContactEmail: string; signature: string; consentType: string; consentDate: string; consentAccepted: boolean; consentDocument: string; documents: ClientDocument[];
};
type LegacyData = Record<string, unknown>;
type ClientDocument = { path: string; category: "Identification" | "Application" | "Evidence" | "Letter" | "Form"; expiresAt: string; version: number; uploadedAt: string };
type Client = ClientForm & { id: string; createdAt: string; createdBy?: string; updatedAt?: string; updatedBy?: string; qualityIssues?: string[]; legacyData?: LegacyData; legacySources?: LegacyData[] };
type ServiceRecord = { id?: string; date?: string; fullName?: string; address?: string; children?: string; adults?: string; seniors?: string; totalHousehold?: string; createdAt?: string };
type ClientAttention = { id: string; clientId: string; clientName: string; serviceCategory: string; subservice: string; requestedDate: string; status: "Requested" | "In Progress" | "Completed" | "Cancelled"; assignedTo: string; followUpDate: string; completionDate: string; comments: string; documents: string[]; createdAt: string };
type ClientCase = { id: string; caseNumber?: string; clientName?: string; clientId?: string; status?: string; assignedTo?: string; followUpDate?: string; createdAt?: string };
type LegacyRow = Record<string, string>;
type ImportPreview = { fileName: string; accepted: Client[]; rejected: { row: number; id: string; name: string; reasons: string[] }[] };
const storageKey = "uccw_clients";
const socialServiceOptions = ["Snap Application", "Snap Recertification", "Periodic Snap Report", "Domestic Violence Support", "DV Case Follow up", "P/A Application", "P/A Recertification", "Eviction Prevention", "Medicaid Application", "Medicaid Recertification", "Housing Application", "Housing Recertification", "Child Care Application", "Homeless Outreach", "School Placement Application", "Affordable Housing Application", "Support Letter", "Self-Employment Income Letter", "Emergency Food", "Diaper Donation", "Passport / Social Security Application"];
const legalImmigrationOptions = ["Naturalization", "Family Petition", "Green Card Renewals", "Remove Conditional on Permanent Resident Card", "Adjustment of Status", "DACA Renewal", "Consular Processes", "TPS", "U-Visa", "VAWA", "Asylum", "601 - Waiver", "Work Authorizations Renewals", "Replacement of Naturalization Certificate", "Certificate of Naturalization", "Change of Address FOIA", "Legal Consultation", "Translation"];
const workerResourceOptions = ["Collection on Unpaid Wages", "Mediation", "Small Claims App. Assistance", "DOL Complaint App. Assistance", "Human Rights Complaint App. Assistance", "District Attorneys Complaint App. Assistance", "WC Consumers Services Complaint App. Assistance", "Worker's Compensation App. Assistance", "WC ID App Assistance", "OSHA-30 Hours", "SST.IO Hours", "Job App Assistance", "DMV Form Filling Appointment", "Resume Writing Assistance", "Unemployment Benefit App Assistance", "Victim of Discrimination", "Victim of Abuse", "Job and Apartment Listing"];
const educationalEmpowermentOptions = ["ESOL", "Computer Training", "Know Your Rights Workshops", "Health and Safety Workshops", "Summer Tutoring Program", "Tenants' Rights Workshop", "DV Awareness Workshops", "Immigration Laws Changes Workshops", "Naturalization Exam Training"];
const healthWellnessOptions = ["Health Insurance", "Yoga with Healing Sounds", "Yoga for Seniors", "Essential Plan", "Medicare Supplemental Basics", "Medicare Advance Application", "Referrals Mental Health", "Emergency Medicaid"];
const serviceIcons: Record<string, string> = { "Social Services": "🤝", "Legal / Immigration": "⚖️", "Worker Resource Center": "🧰", "Educational Empowerment": "🎓", "Health / Wellness / Events": "💚" };
const initialForm: ClientForm = { clientId: "", serviceDate: "", fullName: "", dateOfBirth: "", last4Ssn: "", ethnicity: "", gender: "", address: "", city: "", state: "", zip: "", phone: "", email: "", nationality: "", preferredLanguage: "English", householdSize: "", children: "", adults: "", seniors: "", spouseName: "", maritalStatus: "", immigrationStatus: "", income: "", socialServices: false, otherServices: false, immigration: false, healthAndWellness: false, workersResourceCenter: false, educationalEmpowerment: false, socialServiceDetails: [], legalImmigrationDetails: [], workerResourceDetails: [], educationalEmpowermentDetails: [], healthWellnessDetails: [], photo: "", files: ["", "", "", "", ""], caseNotes: "", tags: [], emergencyContactName: "", emergencyContactRelationship: "", emergencyContactPhone: "", emergencyContactEmail: "", signature: "", consentType: "General Services", consentDate: "", consentAccepted: false, consentDocument: "", documents: [] };

function normalize(item: Partial<Client> & { name?: string }): Client { const id = item.id || crypto.randomUUID(); const files = item.files?.length ? item.files : ["", "", "", "", ""]; return { ...initialForm, ...item, tags: item.tags || [], documents: item.documents?.length ? item.documents : files.filter(Boolean).map((path) => ({ path, category: "Evidence", expiresAt: "", version: 1, uploadedAt: item.createdAt || new Date().toISOString() })), socialServiceDetails: item.socialServiceDetails || [], legalImmigrationDetails: item.legalImmigrationDetails || [], workerResourceDetails: item.workerResourceDetails || [], educationalEmpowermentDetails: item.educationalEmpowermentDetails || [], healthWellnessDetails: item.healthWellnessDetails || [], clientId: item.clientId || `C-${id.slice(0, 8).toUpperCase()}`, fullName: item.fullName || item.name || "", files, id, createdAt: item.createdAt || new Date().toISOString() }; }
function nextId(clients: Client[]) { const highest = clients.reduce((max, client) => Math.max(max, Number(client.clientId.match(/\d+$/)?.[0]) || 0), 0); return `C-${String(highest + 1).padStart(5, "0")}`; }
function readLocal<T>(key: string): T[] { try { return JSON.parse(window.localStorage.getItem(key) || "[]") as T[]; } catch { return []; } }
function normalizedName(name: string) { return name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^\p{L}\p{N}]+/gu, " ").trim().toLowerCase(); }
function documentNames(client: Client) { const legacy = [client.legacyData, ...(client.legacySources || [])].filter(Boolean).flatMap((record) => Object.entries(record || {}).filter(([key, item]) => /^file\s*\d+$/i.test(key) && typeof item === "string" && item.trim()).map(([, item]) => String(item).trim())); return [...new Set([...client.files.filter(Boolean), client.consentDocument, ...legacy].filter(Boolean))]; }
function storedUrl(path: string) { return path.includes("/") && !path.startsWith("data:") ? `/api/files?path=${encodeURIComponent(path)}` : path; }
function fileLabel(path: string) { return path.split("/").at(-1)?.replace(/^[a-f0-9-]+-/i, "") || path; }

export default function ClientManager() {
  const [clients, setClients] = useState<Client[]>([]); const [search, setSearch] = useState(""); const [page, setPage] = useState(1); const [totalClients, setTotalClients] = useState(0); const [loading, setLoading] = useState(true); const [exporting, setExporting] = useState(false); const [loadError, setLoadError] = useState(""); const [reloadKey, setReloadKey] = useState(0); const [isFormOpen, setIsFormOpen] = useState(false); const [editingClient, setEditingClient] = useState<Client | null>(null); const [duplicateCandidates, setDuplicateCandidates] = useState<Client[]>([]); const [historyClient, setHistoryClient] = useState<Client | null>(null); const [historyServices, setHistoryServices] = useState({ food: [] as ServiceRecord[], clothing: [] as ServiceRecord[] }); const [form, setForm] = useState<ClientForm>(initialForm); const [pendingFiles, setPendingFiles] = useState<(File | null)[]>([null, null, null, null, null]); const [pendingConsent, setPendingConsent] = useState<File | null>(null); const [importStatus, setImportStatus] = useState(""); const [importPreview, setImportPreview] = useState<ImportPreview | null>(null); const [formError, setFormError] = useState(""); const [saving, setSaving] = useState(false); const importRef = useRef<HTMLInputElement>(null); const pageSize = 50;
  useEffect(() => { let active = true; setLoading(true); setLoadError(""); const timer = window.setTimeout(() => { loadRemotePage<Client>("clients", page, pageSize, search).then(({ records, total }) => { if (active) { setClients(records.map(normalize)); setTotalClients(total); } }).catch((error: unknown) => { if (active) setLoadError(error instanceof Error ? error.message : "No fue posible cargar los clientes."); }).finally(() => { if (active) setLoading(false); }); }, search ? 350 : 0); return () => { active = false; window.clearTimeout(timer); }; }, [page, search, reloadKey]);
  useEffect(() => { let active = true; Promise.all([loadRemote<ServiceRecord>("food"), loadRemote<ServiceRecord>("clothing")]).then(([food, clothing]) => { if (active) setHistoryServices({ food, clothing }); }); return () => { active = false; }; }, []);
  useEffect(() => { if (!isFormOpen || editingClient || form.fullName.trim().length < 4) { setDuplicateCandidates([]); return; } let active = true; const timer = window.setTimeout(() => { loadRemotePage<Client>("clients", 1, 8, form.fullName).then(({ records }) => { if (!active) return; const name = normalizedName(form.fullName); setDuplicateCandidates(records.map(normalize).filter((item) => normalizedName(item.fullName) === name || Boolean(form.phone && item.phone === form.phone) || Boolean(form.dateOfBirth && item.dateOfBirth === form.dateOfBirth))); }).catch(() => { if (active) setDuplicateCandidates([]); }); }, 400); return () => { active = false; window.clearTimeout(timer); }; }, [form.fullName, form.phone, form.dateOfBirth, isFormOpen, editingClient]);
  function persist(next: Client[]) { setClients(next); }
  function update<K extends keyof ClientForm>(key: K, value: ClientForm[K]) { setForm((current) => ({ ...current, [key]: value })); }
  function openNew() { setEditingClient(null); setFormError(""); setPendingFiles([null, null, null, null, null]); setPendingConsent(null); setForm({ ...initialForm, files: ["", "", "", "", ""] }); setIsFormOpen(true); }
  function openEdit(client: Client) { setEditingClient(client); setFormError(""); setPendingFiles([null, null, null, null, null]); setPendingConsent(null); setForm({ ...client, files: [...client.files] }); setIsFormOpen(true); }
  function updateFile(index: number, file: File | null) { const files = [...form.files]; files[index] = file?.name || files[index] || ""; const next = [...pendingFiles]; next[index] = file; setPendingFiles(next); update("files", files); }
  async function uploadFile(file: File, recordId: string) { const data = new FormData(); data.set("file", file); data.set("module", "clients"); data.set("recordId", recordId); const response = await fetch("/api/files", { method: "POST", body: data }); const result = await response.json().catch(() => null) as { path?: string; error?: string } | null; if (!response.ok || !result?.path) throw new Error(result?.error || `No fue posible cargar ${file.name} (error ${response.status}).`); return result.path; }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const normalizedForm = normalizeDataRecord(form) as ClientForm; const validation = validateDataRecord("clients", normalizedForm); if (validation.length) { setFormError(validation.join(" ")); return; } setForm(normalizedForm); const id = editingClient?.id || crypto.randomUUID(); setSaving(true); setFormError(""); try { const photo = normalizedForm.photo.startsWith("data:") ? await (async () => { const blob = await (await fetch(normalizedForm.photo)).blob(); return uploadFile(new File([blob], "client-photo.jpg", { type: "image/jpeg" }), id); })() : normalizedForm.photo; const signature = normalizedForm.signature.startsWith("data:") ? await (async () => { const blob = await (await fetch(normalizedForm.signature)).blob(); return uploadFile(new File([blob], "client-signature.png", { type: "image/png" }), id); })() : normalizedForm.signature; const consentDocument = normalizedForm.consentDocument.startsWith("data:") ? await (async () => { const blob = await (await fetch(normalizedForm.consentDocument)).blob(); return uploadFile(new File([blob], "signed-consent.pdf", { type: blob.type || "application/pdf" }), id); })() : normalizedForm.consentDocument; const files = await Promise.all(normalizedForm.files.map((file, index) => pendingFiles[index] ? uploadFile(pendingFiles[index]!, id) : file)); const documents = files.filter(Boolean).map((path, index) => { const prior = normalizedForm.documents[index]; return { path, category: prior?.category || "Evidence" as ClientDocument["category"], expiresAt: prior?.expiresAt || "", version: pendingFiles[index] ? (prior?.version || 0) + 1 : prior?.version || 1, uploadedAt: pendingFiles[index] ? new Date().toISOString() : prior?.uploadedAt || new Date().toISOString() }; }); const record = editingClient ? { ...editingClient, ...normalizedForm, id, photo, signature, consentDocument, files, documents } : { id, createdAt: new Date().toISOString(), ...normalizedForm, photo, signature, consentDocument, files, documents, clientId: `C-${id.slice(0, 8).toUpperCase()}` }; await saveRemote("clients", record); setIsFormOpen(false); setReloadKey((value) => value + 1); } catch (error) { setFormError(error instanceof Error ? error.message : "No fue posible guardar el cliente."); } finally { setSaving(false); } }
  async function mergeNewInto(target: Client) { if (!window.confirm(`Combine the entered information into ${target.clientId} · ${target.fullName}? The existing ID and audit history will be preserved.`)) return; setSaving(true); setFormError(""); try { const entered = Object.fromEntries(Object.entries(form).filter(([, value]) => Array.isArray(value) ? value.length > 0 : typeof value === "boolean" ? value : String(value || "").trim())); const merged = { ...target, ...entered, id: target.id, clientId: target.clientId, createdAt: target.createdAt, tags: [...new Set([...(target.tags || []), ...form.tags])], files: [...new Set([...target.files, ...form.files].filter(Boolean))] }; await saveRemote("clients", merged); setIsFormOpen(false); setReloadKey((value) => value + 1); } catch (mergeError) { setFormError(mergeError instanceof Error ? mergeError.message : "Could not combine the records."); } finally { setSaving(false); } }
  async function remove(client: Client) { if (!window.confirm(`¿Eliminar el cliente ${client.fullName}?`)) return; try { await deleteRemote("clients", client.id); setReloadKey((value) => value + 1); } catch (error) { setLoadError(error instanceof Error ? error.message : "No fue posible eliminar el cliente."); } }
  async function importClients(file: File) {
    const rows = parseCsv(await file.text()); const accepted: Client[] = []; const rejected: ImportPreview["rejected"] = []; const seen = new Set<string>();
    rows.forEach((row, index) => { const imported = importRow(row); if (!imported) { rejected.push({ row: index + 2, id: "", name: "", reasons: ["No contiene un identificador válido."] }); return; } const normalized = normalizeDataRecord(imported) as Client; const reasons = validateDataRecord("clients", normalized); if (normalized.fullName.startsWith("Nombre no indicado")) reasons.push("El nombre completo es obligatorio."); if (seen.has(normalized.clientId)) reasons.push("Client ID duplicado dentro del archivo."); if (reasons.length) rejected.push({ row: index + 2, id: normalized.clientId, name: normalized.fullName, reasons }); else { seen.add(normalized.clientId); accepted.push(normalized); } });
    setImportPreview({ fileName: file.name, accepted, rejected });
  }
  async function confirmImport() {
    if (!importPreview?.accepted.length) return; const imported = importPreview.accepted; setImportPreview(null); setImportStatus(`Importando 0 de ${imported.length} clientes…`);
    try {
      // Se conservan las variantes históricas por Client ID. Lotes pequeños evitan
      // exceder el límite de tamaño de las solicitudes cuando hay notas extensas.
      const batchSize = 25;
      for (let index = 0; index < imported.length; index += batchSize) {
        const response = await fetch("/api/records/clients", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ records: imported.slice(index, index + batchSize), mergeExisting: true }) });
        if (!response.ok) throw new Error(); setImportStatus(`Importando ${Math.min(index + batchSize, imported.length)} de ${imported.length} clientes…`);
      }
      setPage(1); setReloadKey((value) => value + 1); setImportStatus(`${imported.length} clientes importados correctamente.`);
    } catch { setImportStatus("No fue posible completar la importación. No se eliminaron los registros ya guardados; vuelva a intentar el archivo."); }
  }
  function downloadRejected() { if (!importPreview?.rejected.length) return; const quote = (value: string | number) => `"${String(value).replace(/"/g, '""')}"`; const csv = ["Row,Client ID,Name,Reasons", ...importPreview.rejected.map((item) => [item.row, item.id, item.name, item.reasons.join(" | ")].map(quote).join(","))].join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); link.download = `UCCW-rejected-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(link.href); }
  async function exportClients() { setExporting(true); setLoadError(""); try { const records = (await loadRemote<Client>("clients")).map(normalize); await exportExcel(records.map((client) => ({ "Client ID": client.clientId, "Service Date": client.serviceDate, "Full Name": client.fullName, "Date Of Birth": client.dateOfBirth, "Last 4 SSN": client.last4Ssn, Ethnicity: client.ethnicity, Gender: client.gender, Address: client.address, City: client.city, State: client.state, Zip: client.zip, Phone: client.phone, Email: client.email, Nationality: client.nationality, "Household Size": client.householdSize, Children: client.children, Adults: client.adults, Seniors: client.seniors, "Spouse Name": client.spouseName, "Marital Status": client.maritalStatus, "Immigration Status": client.immigrationStatus, "Income $": client.income, "Social Services": client.socialServices, "Social Sub-services": client.socialServiceDetails.join(" | "), "Other Services": client.otherServices, Immigration: client.immigration, "Legal / Immigration Sub-services": client.legalImmigrationDetails.join(" | "), "Health And Wellness": client.healthAndWellness, "Health Sub-services": client.healthWellnessDetails.join(" | "), "Workers Resource Center": client.workersResourceCenter, "Worker Sub-services": client.workerResourceDetails.join(" | "), "Educational Empowerment": client.educationalEmpowerment, "Educational Sub-services": client.educationalEmpowermentDetails.join(" | "), Photo: client.photo, File1: client.files[0] || "", File2: client.files[1] || "", File3: client.files[2] || "", File4: client.files[3] || "", File5: client.files[4] || "", "Case Notes": client.caseNotes, "Created At": client.createdAt, "Created By": client.createdBy || "", "Updated At": client.updatedAt || "", "Updated By": client.updatedBy || "" })), "Clients", "UCCW-clients"); } catch (error) { setLoadError(error instanceof Error ? error.message : "No fue posible exportar los clientes."); } finally { setExporting(false); } }
  const visible = clients; const totalPages = Math.max(Math.ceil(totalClients / pageSize), 1);
  return <main className="app-shell clients-page"><Sidebar active="clientes" /><section className="clients-content">
    <div className="page-heading"><div><p className="eyebrow">Administración</p><h1>Clientes</h1><p>Registra y consulta la información de cada cliente.</p></div><div className="heading-actions"><input ref={importRef} type="file" accept=".csv,text/csv" hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) void importClients(file); event.currentTarget.value = ""; }} /><button type="button" className="secondary-button" onClick={() => void exportClients()} disabled={exporting}>{exporting ? "Exportando…" : "Exportar Excel"}</button><button type="button" className="secondary-button" onClick={() => importRef.current?.click()}>Importar CSV</button><button onClick={openNew}>+ Nuevo cliente</button></div></div>
    <div className="clients-toolbar"><input aria-label="Buscar clientes" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Buscar por nombre, ID, últimos 4 SSN, ciudad, correo o teléfono" /><span>{totalClients.toLocaleString("en-US")} cliente{totalClients === 1 ? "" : "s"}</span></div>
    {importStatus && <p className="storage-note">{importStatus}</p>}
    {loadError && <div className="load-error" role="alert"><strong>No fue posible cargar los clientes.</strong><span>{loadError}</span><button type="button" className="secondary-button" onClick={() => setReloadKey((value) => value + 1)}>Reintentar</button></div>}
    <div className="table-card">{loading ? <div className="empty-state"><h2>Cargando clientes…</h2><p>Consultando la información en Supabase.</p></div> : visible.length === 0 ? <div className="empty-state"><h2>No se encontraron clientes</h2><p>{search ? "Prueba con otro nombre, ID, teléfono o ubicación." : "Agrega el primer cliente para comenzar."}</p></div> : <table><thead><tr><th>Client ID</th><th>Cliente</th><th>Fecha de servicio</th><th>Ubicación</th><th>Contacto</th><th>Calidad</th><th>Servicios</th><th aria-label="Acciones"></th></tr></thead><tbody>{visible.map((client) => <tr key={client.id}><td>{client.clientId}</td><td><strong>{client.fullName}</strong><small>SSN: {client.last4Ssn || "No indicado"}</small></td><td>{client.serviceDate || "No indicada"}</td><td><span>{client.city || "Sin ciudad"}</span><small>{client.state} {client.zip}</small></td><td><span>{client.email || "Sin correo"}</span><small>{client.phone || "Sin teléfono"}</small></td><td>{client.qualityIssues?.length ? <span className="quality-badge incomplete" title={client.qualityIssues.join(", ")}>{client.qualityIssues.length} faltante(s)</span> : <span className="quality-badge complete">Completo</span>}</td><td>{[client.socialServices && "Social", client.immigration && "Immigration", client.healthAndWellness && "Health"].filter(Boolean).join(", ") || "No asignados"}</td><td className="actions"><button className="text-button" onClick={() => setHistoryClient(client)}>Ver ficha</button><button className="text-button" onClick={() => openEdit(client)}>Modificar</button><button className="text-button danger" onClick={() => remove(client)}>Eliminar</button></td></tr>)}</tbody></table>}</div>
    {!loading && !loadError && totalPages > 1 && <nav className="pagination" aria-label="Paginación de clientes"><button type="button" className="secondary-button" disabled={page === 1} onClick={() => setPage((value) => Math.max(value - 1, 1))}>Anterior</button><span>Página {page} de {totalPages}</span><button type="button" className="secondary-button" disabled={page >= totalPages} onClick={() => setPage((value) => Math.min(value + 1, totalPages))}>Siguiente</button></nav>}
    <p className="storage-note">Los expedientes se sincronizan con la base de datos central. Por seguridad, el sistema solo conserva los últimos cuatro dígitos del SSN.</p>
  </section>{isFormOpen && <ClientFormModal form={form} editing={Boolean(editingClient)} duplicates={duplicateCandidates} error={formError} saving={saving} update={update} updateFile={updateFile} close={() => setIsFormOpen(false)} save={save} />}{historyClient && <ClientHistoryModal client={historyClient} services={historyServices} close={() => setHistoryClient(null)} />}{importPreview && <div className="modal-backdrop"><section className="modal import-preview-modal" role="dialog" aria-modal="true" aria-labelledby="import-preview-title"><div className="modal-heading"><div><p className="eyebrow">Control de calidad</p><h2 id="import-preview-title">Vista previa de importación</h2></div><button className="close-button" onClick={() => setImportPreview(null)}>×</button></div><div className="import-summary"><article><span>Archivo</span><strong>{importPreview.fileName}</strong></article><article className="accepted"><span>Filas aceptadas</span><strong>{importPreview.accepted.length}</strong></article><article className="rejected"><span>Filas rechazadas</span><strong>{importPreview.rejected.length}</strong></article></div><div className="table-card import-preview-table"><table><thead><tr><th>Fila</th><th>Client ID</th><th>Nombre normalizado</th><th>Resultado</th></tr></thead><tbody>{importPreview.accepted.slice(0, 20).map((item, index) => <tr key={item.id}><td>{index + 2}</td><td>{item.clientId}</td><td>{item.fullName}</td><td><span className="quality-ok">Aceptada</span></td></tr>)}{importPreview.rejected.slice(0, 30).map((item) => <tr key={`rejected-${item.row}`}><td>{item.row}</td><td>{item.id || "—"}</td><td>{item.name || "—"}</td><td><span className="quality-error">{item.reasons.join(" · ")}</span></td></tr>)}</tbody></table></div><p className="storage-note">Se muestran hasta 20 filas aceptadas y 30 rechazadas. Ningún dato se ha guardado todavía.</p><div className="form-actions"><button className="cancel-button" onClick={() => setImportPreview(null)}>Cancelar</button>{importPreview.rejected.length > 0 && <button className="secondary-button" onClick={downloadRejected}>Descargar rechazadas</button>}<button disabled={!importPreview.accepted.length} onClick={() => void confirmImport()}>Importar {importPreview.accepted.length} válidas</button></div></section></div>}</main>;
}

function parseCsv(text: string): LegacyRow[] { const lines: string[][] = [[]]; let value = ""; let quoted = false; for (let index = 0; index < text.length; index += 1) { const char = text[index]; if (char === '"') { if (quoted && text[index + 1] === '"') { value += '"'; index += 1; } else quoted = !quoted; } else if (char === "," && !quoted) { lines.at(-1)?.push(value); value = ""; } else if ((char === "\n" || char === "\r") && !quoted) { if (char === "\r" && text[index + 1] === "\n") index += 1; lines.at(-1)?.push(value); value = ""; lines.push([]); } else value += char; } lines.at(-1)?.push(value); const [headers = [], ...data] = lines; return data.filter((row) => row.some((cell) => cell.trim())).map((row) => Object.fromEntries(headers.map((header, index) => [header.trim(), (row[index] || "").trim()]))); }
function value(row: LegacyRow, key: string) { const item = row[key]?.trim() || ""; return item === "-" ? "" : item; }
function hasValue(row: LegacyRow, key: string) { return Boolean(value(row, key)); }
function dateValue(row: LegacyRow, key: string) { const item = value(row, key).replace(/ 00:00:00$/, ""); if (/^\d{4}-\d{2}-\d{2}$/.test(item)) return item; const match = item.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/); if (!match) return ""; const year = Number(match[3]); return `${year < 100 ? (year < 40 ? 2000 + year : 1900 + year) : year}-${match[1].padStart(2, "0")}-${match[2].padStart(2, "0")}`; }
function numberValue(row: LegacyRow, key: string) { return value(row, key).replace(/[^\d.]/g, ""); }
function importRow(row: LegacyRow): Client | null {
  const primary = "Full_Name" in row; const oldFormat = "Client_ID" in row; const sourceId = value(row, oldFormat ? "Client_ID" : "ClientID") || `LEGACY-${value(row, "ID")}`;
  if (!sourceId || sourceId === "LEGACY-") return null;
  const fullName = primary ? value(row, "Full_Name") : [value(row, "First_Name"), value(row, "Last_Name")].filter(Boolean).join(" ");
  const digits = value(row, primary ? "SSN" : "ID_Number").replace(/\D/g, "");
  const notes = primary ? [value(row, "Notes"), value(row, "Service_Notes"), value(row, "Comments"), value(row, "Comment")].filter(Boolean).join("\n\n") : [value(row, "Notes"), value(row, "Referred_by") && `Referred by: ${value(row, "Referred_by")}`].filter(Boolean).join("\n\n");
  const sensitiveColumn = primary ? "SSN" : "ID_Number"; const legacyData = Object.fromEntries(Object.entries(row).filter(([key]) => key !== sensitiveColumn));
  return { ...initialForm, id: crypto.randomUUID(), createdAt: new Date().toISOString(), clientId: `C-${sourceId}`, serviceDate: dateValue(row, primary ? "Service_Date" : "Date_Entered"), fullName: fullName || `Nombre no indicado (${sourceId})`, dateOfBirth: dateValue(row, primary ? "DOB" : "Date_of_Birth"), last4Ssn: digits.slice(-4), ethnicity: primary ? value(row, "Ethinicity") : "", gender: value(row, primary ? "Gender" : "Sex"), address: value(row, "Address"), city: value(row, "City"), state: value(row, "State"), zip: value(row, oldFormat ? "ZIP_Code" : "Zip"), phone: primary ? value(row, "Phone") : value(row, "Mobile_Phone") || value(row, "Home_Phone") || value(row, "Work_Phone"), email: value(row, primary ? "Email" : "Email_Address") || value(row, "Email"), nationality: value(row, "Nationality"), householdSize: primary ? numberValue(row, "Household_Size") : String((Number(numberValue(row, "Adults_at_Home")) || 0) + (Number(numberValue(row, "Children_at_Home")) || 0)), children: numberValue(row, primary ? "Children" : "Children_at_Home"), adults: numberValue(row, primary ? "Adults" : "Adults_at_Home"), seniors: numberValue(row, "Seniors"), spouseName: value(row, primary ? "Spouse_Name" : "Husband_Wife"), maritalStatus: value(row, "Marital_Status"), immigrationStatus: value(row, "Immigration_Status"), income: numberValue(row, "Income"), socialServices: hasValue(row, "Social_Services"), otherServices: hasValue(row, "Other_Svcs"), immigration: hasValue(row, "Immigration"), healthAndWellness: hasValue(row, "Health"), workersResourceCenter: hasValue(row, "Workers_Resource"), educationalEmpowerment: hasValue(row, "Education"), caseNotes: notes, legacyData } as Client;
}

function ClientHistoryModal({ client, services, close }: { client: Client; services: { food: ServiceRecord[]; clothing: ServiceRecord[] }; close: () => void }) {
  const emptyAttention = { serviceCategory: "", subservice: "", requestedDate: new Date().toISOString().slice(0, 10), status: "Requested" as ClientAttention["status"], assignedTo: "", followUpDate: "", completionDate: "", comments: "" }; const [attentions, setAttentions] = useState<ClientAttention[]>([]); const [cases, setCases] = useState<ClientCase[]>([]); const [previewDocument, setPreviewDocument] = useState(""); const [attention, setAttention] = useState(emptyAttention); const [attentionFiles, setAttentionFiles] = useState<File[]>([]); const [attentionError, setAttentionError] = useState(""); const [attentionLoading, setAttentionLoading] = useState(true); const [attentionSaving, setAttentionSaving] = useState(false);
  async function loadAttentions() { setAttentionLoading(true); setAttentionError(""); try { const [response, caseRecords] = await Promise.all([fetch(`/api/records/client-services?clientId=${encodeURIComponent(client.id)}`, { cache: "no-store" }), loadRemote<ClientCase>("cases")]); const result = await response.json().catch(() => null) as ClientAttention[] | { error?: string } | null; if (!response.ok) throw new Error(!Array.isArray(result) ? result?.error : "No fue posible cargar las atenciones."); setAttentions((Array.isArray(result) ? result : []).sort((a, b) => `${b.createdAt}`.localeCompare(`${a.createdAt}`))); const clientName = normalizedName(client.fullName); setCases(caseRecords.filter((item) => item.clientId === client.id || normalizedName(item.clientName || "") === clientName)); } catch (error) { setAttentionError(error instanceof Error ? error.message : "No fue posible cargar las atenciones."); } finally { setAttentionLoading(false); } }
  useEffect(() => { void loadAttentions(); }, [client.id]);
  async function saveAttention(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setAttentionSaving(true); setAttentionError(""); const id = crypto.randomUUID(); try { const documents = await Promise.all(attentionFiles.map(async (file) => { const data = new FormData(); data.set("file", file); data.set("module", "clients"); data.set("recordId", id); const response = await fetch("/api/files", { method: "POST", body: data }); const result = await response.json().catch(() => null) as { path?: string; error?: string } | null; if (!response.ok || !result?.path) throw new Error(result?.error || `No fue posible cargar ${file.name}.`); return result.path; })); const record: ClientAttention = { id, clientId: client.id, clientName: client.fullName, createdAt: new Date().toISOString(), documents, ...attention }; await saveRemote("client-services", record); setAttention(emptyAttention); setAttentionFiles([]); await loadAttentions(); } catch (error) { setAttentionError(error instanceof Error ? error.message : "No fue posible guardar la atención."); } finally { setAttentionSaving(false); } }
  const name = normalizedName(client.fullName); const documents = documentNames(client);
  const history = [
    ...services.food.filter((item) => normalizedName(item.fullName || "") === name).map((item) => ({ ...item, type: "General Food Distribution", details: `Hogar: ${item.children || 0} niños, ${item.adults || 0} adultos, ${item.seniors || 0} seniors` })),
    ...services.clothing.filter((item) => normalizedName(item.fullName || "") === name).map((item) => ({ ...item, type: "Clothing Drive", details: `Total del hogar: ${item.totalHousehold || "No indicado"}` })),
  ].sort((a, b) => `${b.date || ""}${b.createdAt || ""}`.localeCompare(`${a.date || ""}${a.createdAt || ""}`));
  const requested = [[client.socialServices, "Social Services"], [client.otherServices, "Other Services"], [client.immigration, "Immigration"], [client.healthAndWellness, "Health And Wellness"], [client.workersResourceCenter, "Workers Resource Center"], [client.educationalEmpowerment, "Educational Empowerment"]].filter(([selected]) => selected).map(([, label]) => label);
  const expiredDocuments = client.documents.filter((document) => document.expiresAt && document.expiresAt < new Date().toISOString().slice(0, 10)); const missingDocuments = [!client.documents.some((document) => document.category === "Identification") && "Identification", client.consentAccepted && !client.consentDocument && "Signed consent form"].filter(Boolean) as string[];
  return <div className="modal-backdrop" role="presentation"><section className="modal history-modal" role="dialog" aria-modal="true" aria-labelledby="client-history-title"><div className="modal-heading"><div><p className="eyebrow">Expediente del cliente</p><h2 id="client-history-title">Historial integral</h2></div><button className="close-button" aria-label="Cerrar" onClick={close}>×</button></div>
    <div className="history-profile"><div className="history-photo">{client.photo ? <a href={storedUrl(client.photo)} target="_blank" rel="noreferrer" title="Ver fotografía"><img src={storedUrl(client.photo)} alt={`Foto de ${client.fullName}`} /></a> : <span>{client.fullName.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join("") || "C"}</span>}</div><div><h3>{client.fullName || "Cliente sin nombre"}</h3><p>{client.clientId} · SSN: {client.last4Ssn || "No indicado"}</p><p>{[client.phone, client.email].filter(Boolean).join(" · ") || "Sin contacto registrado"}</p>{client.tags.length > 0 && <div className="client-tags">{client.tags.map((tag) => <span key={tag}>{tag}</span>)}</div>}</div></div>
    <div className="history-grid"><div><strong>Datos personales</strong><span>Nacimiento: {client.dateOfBirth || "No indicado"}</span><span>{client.gender || "Género no indicado"} · {client.ethnicity || "Etnicidad no indicada"}</span><span>{client.nationality || "Nacionalidad no indicada"}</span></div><div><strong>Dirección</strong><span>{client.address || "No indicada"}</span><span>{[client.city, client.state, client.zip].filter(Boolean).join(", ") || "Ubicación no indicada"}</span></div><div><strong>Hogar</strong><span>{client.householdSize || "0"} integrantes</span><span>{client.children || "0"} niños · {client.adults || "0"} adultos · {client.seniors || "0"} seniors</span></div><div><strong>Emergency contact</strong><span>{client.emergencyContactName || "Not provided"}{client.emergencyContactRelationship ? ` · ${client.emergencyContactRelationship}` : ""}</span><span>{[client.emergencyContactPhone, client.emergencyContactEmail].filter(Boolean).join(" · ") || "No contact details"}</span></div><div><strong>Consent</strong><span>{client.consentAccepted ? "Accepted" : "Not confirmed"} · {client.consentType || "General Services"}</span><span>{client.consentDate || "No date"}</span></div><div><strong>Digital signature</strong><span>{client.signature ? "Signature on file" : "Not signed"}</span>{client.signature && <a href={storedUrl(client.signature)} target="_blank" rel="noreferrer">View signature</a>}</div></div>
    <section className="history-section"><h3>Registrar atención</h3><form onSubmit={saveAttention}><div className="form-grid"><Field label="Cliente"><input value={`${client.clientId} · ${client.fullName}`} readOnly /></Field><Field label="Fecha solicitada"><input type="date" required value={attention.requestedDate} onChange={(event) => setAttention({ ...attention, requestedDate: event.target.value })} /></Field><Field label="Servicio principal"><select required value={attention.serviceCategory} onChange={(event) => setAttention({ ...attention, serviceCategory: event.target.value })}><option value="">Seleccione</option><option>Social Services</option><option>Legal / Immigration</option><option>Worker Resource Center</option><option>Educational Empowerment</option><option>Health / Wellness / Events</option><option>General Food Distribution</option><option>Clothing Drive</option></select></Field><Field label="Sub-servicio"><input value={attention.subservice} onChange={(event) => setAttention({ ...attention, subservice: event.target.value })} /></Field><Field label="Estado"><select value={attention.status} onChange={(event) => setAttention({ ...attention, status: event.target.value as ClientAttention["status"] })}><option>Requested</option><option>In Progress</option><option>Completed</option><option>Cancelled</option></select></Field><Field label="Responsable"><input value={attention.assignedTo} onChange={(event) => setAttention({ ...attention, assignedTo: event.target.value })} /></Field><Field label="Fecha de seguimiento"><input type="date" value={attention.followUpDate} onChange={(event) => setAttention({ ...attention, followUpDate: event.target.value })} /></Field><Field label="Fecha de finalización"><input type="date" value={attention.completionDate} onChange={(event) => setAttention({ ...attention, completionDate: event.target.value })} /></Field><Field label="Notas" full><textarea rows={3} value={attention.comments} onChange={(event) => setAttention({ ...attention, comments: event.target.value })} /></Field><Field label="Documentos relacionados" full><input type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,.doc,.docx" onChange={(event) => setAttentionFiles(Array.from(event.target.files || []))} /><small>{attentionFiles.length ? `${attentionFiles.length} archivo(s) seleccionado(s)` : "Sin archivos seleccionados"}</small></Field></div>{attentionError && <p className="form-error" role="alert">{attentionError}</p>}<div className="form-actions"><button type="submit" disabled={attentionSaving}>{attentionSaving ? "Guardando…" : "Agregar al historial"}</button></div></form></section>
    <section className="history-section"><h3>Complete timeline</h3>{attentionLoading ? <p className="history-empty">Loading timeline…</p> : <div className="history-timeline">{[...attentions.map((item) => ({ id: item.id, date: item.requestedDate || item.createdAt, title: `${item.serviceCategory}${item.subservice ? ` · ${item.subservice}` : ""}`, status: item.status, details: item.comments || "No notes.", meta: `Responsible: ${item.assignedTo || "Unassigned"}${item.followUpDate ? ` · Follow-up: ${item.followUpDate}` : ""}`, documents: item.documents })), ...cases.map((item) => ({ id: item.id, date: item.createdAt || item.followUpDate || "", title: `Case ${item.caseNumber || "without number"}`, status: item.status || "Open", details: "Case management record", meta: `Responsible: ${item.assignedTo || "Unassigned"}${item.followUpDate ? ` · Follow-up: ${item.followUpDate}` : ""}`, documents: [] as string[] })), ...history.map((item, index) => ({ id: item.id || `distribution-${index}`, date: item.date || item.createdAt || "", title: item.type, status: "Completed", details: item.details, meta: item.address || "", documents: [] as string[] })), ...(client.caseNotes ? [{ id: "client-notes", date: client.updatedAt || client.createdAt, title: "Client notes", status: "Note", details: client.caseNotes, meta: client.updatedBy || client.createdBy || "Historical record", documents: [] as string[] }] : [])].sort((a, b) => `${b.date}`.localeCompare(`${a.date}`)).map((item) => <article className="history-event" key={`${item.id}-${item.title}`}><strong>{item.title}</strong><span>{item.date || "Date unavailable"} · {item.status}</span><p>{item.details}</p><small>{item.meta}</small>{item.documents.length > 0 && <div className="attention-documents">{item.documents.map((document) => <a key={document} href={storedUrl(document)} target="_blank" rel="noreferrer">{fileLabel(document)}</a>)}</div>}</article>)}</div>}</section>
    <section className="history-section"><h3>Servicios recibidos</h3>{history.length ? <div className="history-timeline">{history.map((item, index) => <article className="history-event" key={`${item.type}-${item.id || index}`}><strong>{item.type}</strong><span>{item.date || "Fecha no indicada"}</span><p>{item.details}</p>{item.address && <small>{item.address}</small>}</article>)}</div> : <p className="history-empty">No hay atenciones Food o Clothing vinculadas a este nombre.</p>}</section>
    <section className="history-section"><h3>Servicios solicitados</h3><p>{requested.length ? requested.join(" · ") : "No hay servicios solicitados registrados."}</p>{client.socialServiceDetails?.length ? <><strong>Social Services</strong><p>{client.socialServiceDetails.join(" · ")}</p></> : null}{client.legalImmigrationDetails?.length ? <><strong>Legal / Immigration</strong><p>{client.legalImmigrationDetails.join(" · ")}</p></> : null}{client.workerResourceDetails?.length ? <><strong>Worker Resource Center</strong><p>{client.workerResourceDetails.join(" · ")}</p></> : null}{client.educationalEmpowermentDetails?.length ? <><strong>Educational Empowerment</strong><p>{client.educationalEmpowermentDetails.join(" · ")}</p></> : null}{client.healthWellnessDetails?.length ? <><strong>Health / Wellness / Events</strong><p>{client.healthWellnessDetails.join(" · ")}</p></> : null}</section>
    <section className="history-section"><h3>Notas del caso</h3><p className="case-notes">{client.caseNotes || "No hay notas registradas."}</p></section>
    <section className="history-section"><div className="panel-heading"><div><h3>Document management</h3><p>{client.documents.length} managed document{client.documents.length === 1 ? "" : "s"}</p></div></div>{(expiredDocuments.length > 0 || missingDocuments.length > 0) && <div className="document-alerts">{expiredDocuments.map((document) => <span key={document.path}>Expired: {fileLabel(document.path)} ({document.expiresAt})</span>)}{missingDocuments.map((item) => <span key={item}>Missing: {item}</span>)}</div>}{client.documents.length ? <div className="managed-document-list">{client.documents.map((document) => <article key={`${document.path}-${document.version}`}><div><strong>{fileLabel(document.path)}</strong><span>{document.category} · Version {document.version}</span><small>{document.expiresAt ? `Expires ${document.expiresAt}` : "No expiration date"}</small></div><button type="button" className="text-button" onClick={() => setPreviewDocument(document.path)}>Preview</button><a href={storedUrl(document.path)} download={fileLabel(document.path)}>Download</a></article>)}</div> : documents.length ? <ul className="history-documents">{documents.map((document, index) => <li key={`${document}-${index}`}>{document.includes("/") ? <><button type="button" className="text-button" onClick={() => setPreviewDocument(document)}>Preview: {fileLabel(document)}</button><a href={storedUrl(document)} download={fileLabel(document)}>Download</a></> : document}</li>)}</ul> : <p className="history-empty">No documents registered.</p>}</section>
    <section className="history-section audit-section"><h3>Auditoría</h3><p>Creado por: <strong>{client.createdBy || "Registro histórico"}</strong> · {new Date(client.createdAt).toLocaleString("es-DO")}</p><p>Última modificación: <strong>{client.updatedBy || client.createdBy || "No disponible"}</strong> · {client.updatedAt ? new Date(client.updatedAt).toLocaleString("es-DO") : "Sin modificaciones registradas"}</p></section>
  </section>{previewDocument && <div className="document-preview-backdrop"><section className="document-preview"><div className="modal-heading"><h2>{fileLabel(previewDocument)}</h2><button type="button" className="close-button" onClick={() => setPreviewDocument("")}>×</button></div><iframe title={fileLabel(previewDocument)} src={storedUrl(previewDocument)} /><div className="form-actions"><a className="secondary-button" href={storedUrl(previewDocument)} download={fileLabel(previewDocument)}>Download</a><button type="button" onClick={() => setPreviewDocument("")}>Close</button></div></section></div>}</div>;
}

function ClientFormModal({ form, editing, duplicates, error, saving, update, updateFile, close, save }: { form: ClientForm; editing: boolean; duplicates: Client[]; error: string; saving: boolean; update: <K extends keyof ClientForm>(key: K, value: ClientForm[K]) => void; updateFile: (index: number, file: File | null) => void; close: () => void; save: (event: FormEvent<HTMLFormElement>) => void }) {
  return <div className="modal-backdrop" role="presentation"><section className="modal client-modal" role="dialog" aria-modal="true" aria-labelledby="client-form-title"><div className="modal-heading"><h2 id="client-form-title">{editing ? "Editar cliente" : "Nuevo cliente"}</h2><button className="close-button" aria-label="Cerrar" onClick={close}>×</button></div><form onSubmit={save}>
    <h3>Información de servicio</h3><div className="form-grid"><Field label="Client ID"><input value={form.clientId || "Se genera al guardar"} readOnly /></Field><Field label="Service Date"><input type="date" value={form.serviceDate} onChange={(e) => update("serviceDate", e.target.value)} required /></Field><Field label="Full Name"><input value={form.fullName} onChange={(e) => update("fullName", e.target.value)} required /></Field><Field label="Date Of Birth"><input type="date" value={form.dateOfBirth} onChange={(e) => update("dateOfBirth", e.target.value)} /></Field><Field label="Last 4 SSN"><input inputMode="numeric" maxLength={4} value={form.last4Ssn} onChange={(e) => update("last4Ssn", e.target.value.replace(/\D/g, "").slice(0, 4))} /></Field><Field label="Ethnicity"><input value={form.ethnicity} onChange={(e) => update("ethnicity", e.target.value)} /></Field><Field label="Gender"><select value={form.gender} onChange={(e) => update("gender", e.target.value)}><option value="">Seleccione</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Prefer not to say</option></select></Field></div>
    {duplicates.length > 0 && <div className="duplicate-warning" role="alert"><strong>Possible duplicate client</strong><p>Review the match before creating another record. Combining preserves the existing client ID and audit history.</p>{duplicates.map((item) => <span key={item.id}>{item.clientId} · {item.fullName}{item.dateOfBirth ? ` · ${item.dateOfBirth}` : ""}<button type="button" className="text-button" onClick={async () => { if (!window.confirm(`Combine the entered data into ${item.clientId}?`)) return; const entered = Object.fromEntries(Object.entries(form).filter(([, value]) => Array.isArray(value) ? value.length : typeof value === "boolean" ? value : String(value || "").trim())); await saveRemote("clients", { ...item, ...entered, id: item.id, clientId: item.clientId, createdAt: item.createdAt, tags: [...new Set([...(item.tags || []), ...form.tags])], files: [...new Set([...item.files, ...form.files].filter(Boolean))] }); window.location.reload(); }}>Combine into this record</button></span>)}</div>}
    <h3>Dirección y contacto</h3><div className="form-grid"><Field label="Address" full><input value={form.address} onChange={(e) => update("address", e.target.value)} /></Field><Field label="City"><input value={form.city} onChange={(e) => update("city", e.target.value)} /></Field><Field label="State"><input maxLength={2} value={form.state} onChange={(e) => update("state", e.target.value.toUpperCase())} placeholder="NY" /></Field><Field label="Zip"><input inputMode="numeric" pattern="\d{5}(-\d{4})?" title="Use 12345 o 12345-6789" value={form.zip} onChange={(e) => update("zip", e.target.value)} /></Field><Field label="Phone"><input type="tel" pattern="[+()\-\s\d]{10,25}" title="Ingrese un teléfono válido de al menos 10 dígitos" value={form.phone} onChange={(e) => update("phone", e.target.value)} /></Field><Field label="Email" full><input type="email" value={form.email} onChange={(e) => update("email", e.target.value)} /></Field><Field label="Nationality"><input value={form.nationality} onChange={(e) => update("nationality", e.target.value)} /></Field><Field label="Preferred language"><select value={form.preferredLanguage} onChange={(e) => update("preferredLanguage", e.target.value as ClientForm["preferredLanguage"])}><option>English</option><option>Spanish</option><option>Other</option></select></Field></div>
    <h3>Hogar e información personal</h3><div className="form-grid"><Field label="Household Size"><input type="number" min="0" value={form.householdSize} onChange={(e) => update("householdSize", e.target.value)} /></Field><Field label="Children"><input type="number" min="0" value={form.children} onChange={(e) => update("children", e.target.value)} /></Field><Field label="Adults"><input type="number" min="0" value={form.adults} onChange={(e) => update("adults", e.target.value)} /></Field><Field label="Seniors"><input type="number" min="0" value={form.seniors} onChange={(e) => update("seniors", e.target.value)} /></Field><Field label="Spouse Name"><input value={form.spouseName} onChange={(e) => update("spouseName", e.target.value)} /></Field><Field label="Marital Status"><input value={form.maritalStatus} onChange={(e) => update("maritalStatus", e.target.value)} /></Field><Field label="Immigration Status"><input value={form.immigrationStatus} onChange={(e) => update("immigrationStatus", e.target.value)} /></Field><Field label="Income $"><input type="number" min="0" step="0.01" value={form.income} onChange={(e) => update("income", e.target.value)} /></Field></div>
    <h3>Priority and emergency contact</h3><div className="client-tag-picker"><Check label="Urgent" checked={form.tags.includes("Urgent")} onChange={(value) => update("tags", value ? [...form.tags, "Urgent"] : form.tags.filter((tag) => tag !== "Urgent"))} /><Check label="Vulnerable" checked={form.tags.includes("Vulnerable")} onChange={(value) => update("tags", value ? [...form.tags, "Vulnerable"] : form.tags.filter((tag) => tag !== "Vulnerable"))} /><Check label="Priority follow-up" checked={form.tags.includes("Priority follow-up")} onChange={(value) => update("tags", value ? [...form.tags, "Priority follow-up"] : form.tags.filter((tag) => tag !== "Priority follow-up"))} /></div><div className="form-grid"><Field label="Emergency contact name"><input value={form.emergencyContactName} onChange={(event) => update("emergencyContactName", event.target.value)} /></Field><Field label="Relationship"><input value={form.emergencyContactRelationship} onChange={(event) => update("emergencyContactRelationship", event.target.value)} /></Field><Field label="Emergency phone"><input type="tel" value={form.emergencyContactPhone} onChange={(event) => update("emergencyContactPhone", event.target.value)} /></Field><Field label="Emergency email"><input type="email" value={form.emergencyContactEmail} onChange={(event) => update("emergencyContactEmail", event.target.value)} /></Field></div>
    <h3>Servicios solicitados</h3><div className="service-grid" style={{ gridTemplateColumns: "repeat(6, minmax(0, 1fr))", gap: 6 }}><Check label="Social Services" checked={form.socialServices} onChange={(v) => update("socialServices", v)} /><Check label="Other Services" checked={form.otherServices} onChange={(v) => update("otherServices", v)} /><Check label="Immigration" checked={form.immigration} onChange={(v) => update("immigration", v)} /><Check label="Health And Wellness" checked={form.healthAndWellness} onChange={(v) => update("healthAndWellness", v)} /><Check label="Workers Resource Center" checked={form.workersResourceCenter} onChange={(v) => update("workersResourceCenter", v)} /><Check label="Educational Empowerment" checked={form.educationalEmpowerment} onChange={(v) => update("educationalEmpowerment", v)} /></div><div className="subservice-groups">{form.socialServices && <SubserviceGroup title="Social Services" options={socialServiceOptions} selected={form.socialServiceDetails} onChange={(value) => update("socialServiceDetails", value)} />}{form.immigration && <SubserviceGroup title="Legal / Immigration" options={legalImmigrationOptions} selected={form.legalImmigrationDetails} onChange={(value) => update("legalImmigrationDetails", value)} />}{form.workersResourceCenter && <SubserviceGroup title="Worker Resource Center" options={workerResourceOptions} selected={form.workerResourceDetails} onChange={(value) => update("workerResourceDetails", value)} />}{form.educationalEmpowerment && <SubserviceGroup title="Educational Empowerment" options={educationalEmpowermentOptions} selected={form.educationalEmpowermentDetails} onChange={(value) => update("educationalEmpowermentDetails", value)} />}{form.healthAndWellness && <SubserviceGroup title="Health / Wellness / Events" options={healthWellnessOptions} selected={form.healthWellnessDetails} onChange={(value) => update("healthWellnessDetails", value)} />}</div>
    <h3>Signature and consent</h3><SignaturePad value={form.signature} onChange={(value) => update("signature", value)} /><div className="form-grid"><Field label="Consent form type"><select value={form.consentType} onChange={(event) => update("consentType", event.target.value)}><option>General Services</option><option>Release of Information</option><option>Photo Authorization</option><option>Program Participation</option></select></Field><Field label="Consent date"><input type="date" value={form.consentDate} onChange={(event) => update("consentDate", event.target.value)} /></Field><Field label="Consent confirmation" full><label className="consent-check"><input type="checkbox" checked={form.consentAccepted} onChange={(event) => update("consentAccepted", event.target.checked)} /> The client reviewed and accepted this consent.</label></Field><Field label="Signed consent document" full><input type="file" accept="application/pdf,image/jpeg,image/png" onChange={(event) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => update("consentDocument", String(reader.result || "")); reader.readAsDataURL(file); }} /><small>{form.consentDocument ? "Consent document selected or stored" : "No consent document selected"}</small></Field></div>
    <h3>Photo, managed documents, and notes</h3><PhotoCapture photo={form.photo} updatePhoto={(photo) => update("photo", photo)} /><div className="file-grid">{form.files.map((file, index) => { const metadata = form.documents[index] || { path: file, category: "Evidence" as const, expiresAt: "", version: 0, uploadedAt: "" }; const updateMetadata = (values: Partial<ClientDocument>) => { const documents = [...form.documents]; documents[index] = { ...metadata, ...values }; update("documents", documents); }; return <label className="file-field managed-document" key={index}>Document {index + 1}<span>{file ? fileLabel(file) : "No file selected"}</span><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf,.doc,.docx" onChange={(e) => updateFile(index, e.target.files?.[0] || null)} /><select aria-label={`Document ${index + 1} category`} value={metadata.category} onChange={(event) => updateMetadata({ category: event.target.value as ClientDocument["category"] })}><option>Identification</option><option>Application</option><option>Evidence</option><option>Letter</option><option>Form</option></select><span className="document-date-label">Expiration date</span><input type="date" value={metadata.expiresAt} onChange={(event) => updateMetadata({ expiresAt: event.target.value })} /><small>{metadata.version ? `Version ${metadata.version}` : "New document"}</small></label>; })}</div><Field label="Case Notes" full><textarea rows={4} value={form.caseNotes} onChange={(e) => update("caseNotes", e.target.value)} /></Field>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="cancel-button" disabled={saving} onClick={close}>Cancelar</button><button type="submit" disabled={saving}>{saving ? "Guardando…" : editing ? "Guardar cambios" : "Registrar cliente"}</button></div>
  </form></section></div>;
}
function Field({ label, children, full = false }: { label: string; children: React.ReactNode; full?: boolean }) { return <label className={full ? "full-width" : ""}>{label}{children}</label>; }
function Check({ label, checked, onChange }: { label: string; checked: boolean; onChange: (value: boolean) => void }) { return <label className="service-check"><input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} />{label}</label>; }
function SignaturePad({ value, onChange }: { value: string; onChange: (value: string) => void }) { const canvasRef = useRef<HTMLCanvasElement>(null); const drawing = useRef(false); function point(event: React.PointerEvent<HTMLCanvasElement>) { const canvas = canvasRef.current!; const box = canvas.getBoundingClientRect(); return { x: (event.clientX - box.left) * canvas.width / box.width, y: (event.clientY - box.top) * canvas.height / box.height }; } function start(event: React.PointerEvent<HTMLCanvasElement>) { drawing.current = true; const context = canvasRef.current?.getContext("2d"); const position = point(event); context?.beginPath(); context?.moveTo(position.x, position.y); event.currentTarget.setPointerCapture(event.pointerId); } function move(event: React.PointerEvent<HTMLCanvasElement>) { if (!drawing.current) return; const context = canvasRef.current?.getContext("2d"); const position = point(event); if (context) { context.lineWidth = 2; context.lineCap = "round"; context.strokeStyle = "#102a43"; context.lineTo(position.x, position.y); context.stroke(); } } function finish() { if (!drawing.current) return; drawing.current = false; const canvas = canvasRef.current; if (canvas) onChange(canvas.toDataURL("image/png")); } return <div className="signature-pad"><strong>Client digital signature</strong>{value && !value.startsWith("data:") ? <img src={storedUrl(value)} alt="Client signature" /> : <canvas ref={canvasRef} width={700} height={180} onPointerDown={start} onPointerMove={move} onPointerUp={finish} onPointerCancel={finish} />}<div><button type="button" className="secondary-button" onClick={() => { const canvas = canvasRef.current; canvas?.getContext("2d")?.clearRect(0, 0, canvas.width, canvas.height); onChange(""); }}>Clear signature</button>{value && !value.startsWith("data:") && <button type="button" className="text-button" onClick={() => onChange("")}>Replace signature</button>}</div></div>; }
function SubserviceGroup({ title, options, selected, onChange }: { title: string; options: string[]; selected: string[]; onChange: (value: string[]) => void }) { const [expanded, setExpanded] = useState(false); function toggle(option: string) { onChange(selected.includes(option) ? selected.filter((item) => item !== option) : [...selected, option]); } return <><fieldset className="subservice-group"><legend><button type="button" className="subservice-toggle" style={{ background: "transparent", color: "#12345b", padding: "2px 4px", width: "auto", minWidth: 0, fontSize: ".9rem", boxShadow: "none" }} aria-expanded={expanded} aria-label={`${title}, ${selected.length} sub-servicios seleccionados`} onClick={() => setExpanded(true)}><span aria-hidden="true" style={{ marginRight: 6 }}>{serviceIcons[title] || "•"}</span>{title}<span style={{ color: "#1769aa", fontSize: ".82rem", fontWeight: 700, marginLeft: 8 }}>({selected.length})</span><b aria-hidden="true" style={{ marginLeft: 4 }}>+</b></button></legend></fieldset>{expanded && <div className="modal-backdrop" role="presentation" onClick={() => setExpanded(false)}><section className="modal service-modal subservice-modal" style={{ maxHeight: "calc(100vh - 80px)", overflowY: "auto" }} role="dialog" aria-modal="true" aria-label={title} onClick={(event) => event.stopPropagation()}><div className="modal-heading"><h2>{serviceIcons[title] || "•"} {title}</h2><button type="button" className="close-button" aria-label="Cerrar" onClick={() => setExpanded(false)}>×</button></div><p>Seleccione los sub-servicios que se van a realizar.</p><div className="subservice-grid" style={{ gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 8 }}>{options.map((option) => <label className="service-check" key={option}><input type="checkbox" checked={selected.includes(option)} onChange={() => toggle(option)} />{option}</label>)}</div><div className="form-actions"><button type="button" onClick={() => setExpanded(false)}>Aceptar</button></div></section></div>}</>; }
function PhotoCapture({ photo, updatePhoto }: { photo: string; updatePhoto: (photo: string) => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const [stream, setStream] = useState<MediaStream | null>(null); const [cameraError, setCameraError] = useState("");
  function stopCamera() { stream?.getTracks().forEach((track) => track.stop()); setStream(null); }
  async function openCamera() { try { setCameraError(""); setStream(await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" }, audio: false })); } catch { setCameraError("No se pudo acceder a la cámara. Verifique los permisos del navegador."); } }
  function takePhoto() { const video = videoRef.current; if (!video) return; const canvas = document.createElement("canvas"); canvas.width = video.videoWidth || 640; canvas.height = video.videoHeight || 480; canvas.getContext("2d")?.drawImage(video, 0, 0, canvas.width, canvas.height); updatePhoto(canvas.toDataURL("image/jpeg", 0.8)); stopCamera(); }
  useEffect(() => { if (stream && videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play().catch(() => setCameraError("No se pudo iniciar la cámara.")); } return () => { stream?.getTracks().forEach((track) => track.stop()); }; }, [stream]);
  return <div className="photo-capture"><strong>Foto</strong>{photo && <img src={storedUrl(photo)} alt="Foto del cliente" />} {stream && <video ref={videoRef} muted playsInline />}<div><button type="button" className="secondary-button" onClick={stream ? takePhoto : openCamera}>{stream ? "Tomar fotografía" : "Abrir cámara"}</button>{stream && <button type="button" className="text-button" onClick={stopCamera}>Cancelar cámara</button>}{photo && <button type="button" className="text-button danger" onClick={() => updatePhoto("")}>Eliminar foto</button>}</div>{cameraError && <small className="form-error">{cameraError}</small>}</div>;
}

